<script setup lang="ts">
import { computed, onMounted, ref } from "vue";
import { useI18n } from "vue-i18n";
import type { FormInstance, FormRules } from "element-plus";
import { ElMessage } from "element-plus";
import { ManagedDialog } from "@appnexus/ui";
import { sceneContract } from "./workflow";
import type { DesignContract, PrintApi, PrintRow } from "./index";

/** 配置式打印入口；用 Element Plus 动态表单承载契约字段，不要求用户填写 JSON 或设备命令。 */
const props=defineProps<{api:PrintApi;capabilities:string[];errorText:(error:unknown)=>string;section:"contracts"|"scenes"|"documents"|"queues";query?:string;initialTemplateId?:string}>();
const {t,locale}=useI18n();
const scenes=ref<PrintRow[]>([]),documents=ref<PrintRow[]>([]),templates=ref<PrintRow[]>([]),devices=ref<PrintRow[]>([]),queues=ref<Record<string,unknown>[]>([]),contracts=ref<DesignContract[]>([]);
const busy=ref(false),loading=ref(false),error=ref(""),sceneOpen=ref(false),documentOpen=ref(false),outputOpen=ref(false);
const sceneForm=ref<Record<string,any>>({}),documentScene=ref(""),number=ref(""),data=ref<Record<string,any>>({}),target=ref<PrintRow>();
const sceneFormRef=ref<FormInstance>();
/** 编码与服务端 PrintRules 一致：1—64 位、字母开头；已保存编码作为稳定集成标识不可修改。 */
const sceneRules=computed<FormRules>(()=>({
  code:[{required:true,pattern:/^[A-Za-z][A-Za-z0-9_.-]{0,63}$/,message:t("printing.flow.sceneCodeInvalid"),trigger:"blur"},
    {validator:(_rule,value,callback)=>callback(scenes.value.some(row=>row.id!==sceneForm.value.id&&String(row.code).toLowerCase()===String(value).toLowerCase())?new Error(t("printing.flow.sceneCodeDuplicate")):undefined),trigger:"blur"}],
  name:[{required:true,whitespace:true,max:128,message:t("printing.flow.required"),trigger:"blur"}],
  templateId:[{required:true,message:t("printing.flow.required"),trigger:"change"}]
}));
/**
 * 仅复制用户主动选择的公开场景标识；浏览器拒绝剪贴板访问时保留可选文本并提示手动复制。
 * @param value 服务端返回的场景编码或 UUID；不得传入业务数据、凭据或 Token。
 * @returns 复制完成或失败提示完成后结束，不修改场景配置。
 */
async function copySceneIdentifier(value:unknown){try{await navigator.clipboard.writeText(String(value));ElMessage.success(t("printing.flow.identifierCopied"))}catch{ElMessage.error(t("printing.flow.identifierCopyFailed"))}}
const designAfterSave=ref(false);
const contractOpen=ref(false),contractForm=ref<DesignContract>({code:"",nameZh:"",nameEn:"",designOnly:false,fields:[]});
const printMode=ref<"SILENT"|"PREVIEW">("PREVIEW");
const output=ref<{deviceId:string;outputType:"PDF"|"PRINTER";copies:number}>({deviceId:"",outputType:"PDF",copies:1});
let requestId=crypto.randomUUID();
let submittedOptions:{deviceId:string|null;outputType:"PDF"|"PRINTER";copies:number}|undefined;
const can=(value:string)=>props.capabilities.includes(value);
const english=computed(()=>locale.value.startsWith("en"));
const currentScene=computed(()=>scenes.value.find(value=>value.id===documentScene.value));
const contract=computed(()=>contracts.value.find(value=>value.code===currentScene.value?.data_contract));
const scalarFields=computed(()=>contract.value?.fields.filter(value=>!value.columns)??[]);
const tableFields=computed(()=>contract.value?.fields.filter(value=>value.columns)??[]);
const matchingTemplates=computed(()=>templates.value.filter(value=>value.published_version));
const sceneReady=computed(()=>matchingTemplates.value.length>0);
const visible=<T extends Record<string,unknown>>(rows:T[])=>rows.filter(row=>!props.query||Object.values(row).some(value=>String(value??"").toLowerCase().includes(props.query!.toLowerCase())));
function selectTemplate(){sceneForm.value.contract=sceneContract(templates.value,sceneForm.value.templateId)}

/** 独立分区读取真实配置；失败保留已有内容，不把网络失败伪装成空列表。 */
async function load(){loading.value=true;error.value="";try{
  if(props.section!=="contracts"&&props.section!=="queues")scenes.value=await props.api.scenes();
  if(props.section!=="queues")contracts.value=await props.api.designContracts();
  if(props.section==="documents"&&can("submit")){documents.value=await props.api.documents();devices.value=await props.api.devices()}
  if(props.section==="scenes"&&can("publish"))templates.value=await props.api.templates();
  if(props.section==="queues"&&can("devices"))queues.value=await props.api.clientQueues();
}catch(e){error.value=props.errorText(e)}finally{loading.value=false}}
onMounted(async()=>{await load();if(props.section==="scenes"&&props.initialTemplateId&&sceneReady.value)editScene()});
defineExpose({refresh:load});
async function run(action:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value="";try{await action()}catch(e){error.value=props.errorText(e)}finally{busy.value=false}}
function editScene(row?:Record<string,unknown>){error.value="";if(!row&&!sceneReady.value)return;sceneForm.value=row?{...row,contract:row.data_contract,templateId:row.template_id}:{code:"scene_"+crypto.randomUUID(),name:"",contract:"",templateId:props.initialTemplateId??"",copies:1,enabled:true,revision:-1};selectTemplate();sceneOpen.value=true}
function newContract(){designAfterSave.value=false;contractForm.value={code:"custom_"+crypto.randomUUID().replaceAll("-","")+".v1",nameZh:"",nameEn:"",designOnly:false,fields:[]};contractOpen.value=true}
function addContractField(){const index=contractForm.value.fields.length+1;contractForm.value.fields.push({key:"field"+index,labelZh:"",labelEn:"",sample:""})}
function setFieldType(row:Record<string,unknown>,table:boolean){const field=row as unknown as DesignContract["fields"][number];if(table)field.columns=[{key:"item",labelZh:"名称",labelEn:"Item",sample:""}];else delete field.columns}
function addColumn(row:Record<string,unknown>){const field=row as unknown as DesignContract["fields"][number];field.columns!.push({key:"column"+(field.columns!.length+1),labelZh:"",labelEn:"",sample:""})}
async function saveContract(){await run(async()=>{contracts.value=await props.api.createContract(contractForm.value);contractOpen.value=false;emit("contractsChanged",contracts.value,contractForm.value.code);if(designAfterSave.value)emit("createTemplate",contractForm.value.code);ElMessage.success(t("printing.saved"))})}
async function saveScene(){if(!await sceneFormRef.value?.validate().catch(()=>false))return;await run(async()=>{scenes.value=await props.api.saveScene(sceneForm.value.id,sceneForm.value);sceneOpen.value=false;ElMessage.success(t("printing.saved"))})}
function resetData(){data.value=Object.fromEntries((contract.value?.fields??[]).map(field=>[field.key,field.columns?[]:field.type==="NUMBER"?undefined:field.type==="BOOLEAN"?undefined:""]))}
function newDocument(){documentScene.value=String(scenes.value.find(value=>value.enabled)?.id??"");number.value="";resetData();documentOpen.value=true}
function addLine(key:string){if(data.value[key].length>=500)return;const field=contract.value!.fields.find(value=>value.key===key)!;data.value[key].push(Object.fromEntries(field.columns!.map(column=>[column.key,""])))}
async function saveDocument(){if(!number.value.trim()||!documentScene.value){error.value=t("printing.flow.required");return}await run(async()=>{if(contract.value?.fields.some(field=>field.key==="documentNumber"))data.value.documentNumber=number.value.trim();documents.value=await props.api.saveDocument({sceneId:documentScene.value,number:number.value,data:data.value});documentOpen.value=false;ElMessage.success(t("printing.saved"))})}
function openOutput(row:Record<string,unknown>){error.value="";target.value=row as PrintRow;output.value={deviceId:String(devices.value.find(value=>value.enabled)?.id??""),outputType:"PDF",copies:Number(scenes.value.find(value=>value.id===row.scene_id)?.copies??1)};requestId=crypto.randomUUID();submittedOptions=undefined;outputOpen.value=true}
/** 同一次提交保留幂等键，网络错误重试不会重复出纸；变更选项时由用户重新打开提交窗口。 */
async function submit(){if(output.value.outputType==="PRINTER"&&printMode.value==="SILENT"&&!output.value.deviceId){error.value=t("printing.flow.noDevices");return}await run(async()=>{submittedOptions??={...output.value,deviceId:output.value.outputType==="PDF"?null:output.value.deviceId,copies:output.value.outputType==="PDF"?1:output.value.copies};if(output.value.outputType==="PDF")await props.api.printDocument(target.value!.id,submittedOptions,requestId);else{const result=await props.api.createOutput(target.value!.id,{mode:printMode.value,deviceId:output.value.deviceId||null,copies:output.value.copies},requestId);if(printMode.value==="PREVIEW")emit("preview",result.id)}outputOpen.value=false;ElMessage.success(t("printing.flow.queued"));emit("submitted")})}
const emit=defineEmits<{submitted:[];preview:[id:string];contractsChanged:[contracts:DesignContract[],code:string];createTemplate:[code?:string]}>();
async function registerQueue(row:Record<string,unknown>){await run(async()=>{await props.api.saveDevice(undefined,{code:"device_"+crypto.randomUUID(),name:String(row.queue_name),siteCode:String(row.site_code),systemName:String(row.queue_name),enabled:true,capabilities:{}});devices.value=can("submit")?await props.api.devices():[];ElMessage.success(t("printing.saved"))})}
</script>

<template>
  <section v-loading="loading" class="flow-workspace">

    <el-alert v-if="error" :title="error" type="error" :closable="false"><el-button link @click="load">{{t('account.retry')}}</el-button></el-alert>
    <template v-if="section==='contracts'">
      <header><h2>{{t('printing.dataContract')}}</h2><el-button v-if="can('design')" type="primary" :disabled="loading" @click="newContract">{{t('printing.flow.createContract')}}</el-button></header>
      <el-table :data="visible(contracts as unknown as Record<string,unknown>[])"><el-table-column :label="t('printing.name')" min-width="180"><template #default="{row}">{{english?row.nameEn:row.nameZh}}</template></el-table-column><el-table-column prop="code" :label="t('printing.code')" min-width="200"/><el-table-column v-if="can('design')" :label="t('printing.operations')" width="180"><template #default="{row}"><el-button link type="primary" @click="emit('createTemplate',String(row.code))">{{t('printing.flow.designFromContract')}}</el-button></template></el-table-column></el-table>
    </template>
    <template v-if="section==='scenes'">
      <el-alert v-if="!loading&&!sceneReady" :title="t('printing.flow.needPublishedTemplate')" type="info" :closable="false"><el-button link type="primary" @click="emit('createTemplate')">{{t('printing.flow.goTemplates')}}</el-button></el-alert>
      <header><h2>{{t('printing.flow.scenes')}}</h2><el-button v-if="can('publish')" type="primary" :disabled="loading||!sceneReady" @click="editScene()">{{t('printing.flow.createScene')}}</el-button></header>
      <el-table :data="visible(scenes)" row-key="id"><el-table-column prop="name" :label="t('printing.name')" min-width="160"/><el-table-column :label="t('printing.flow.sceneCode')" min-width="260"><template #default="{row}"><span class="scene-identifier">{{row.code}}</span><el-button link type="primary" :aria-label="t('printing.flow.copySceneCode')" @click="copySceneIdentifier(row.code)">{{t('printing.flow.copy')}}</el-button></template></el-table-column><el-table-column type="expand"><template #default="{row}"><el-descriptions :column="1"><el-descriptions-item :label="t('printing.flow.sceneId')"><span class="scene-identifier">{{row.id}}</span><el-button link type="primary" :aria-label="t('printing.flow.copySceneId')" @click="copySceneIdentifier(row.id)">{{t('printing.flow.copy')}}</el-button></el-descriptions-item></el-descriptions></template></el-table-column><el-table-column :label="t('printing.template')" min-width="180"><template #default="{row}">{{templates.find(value=>value.id===row.template_id)?.name??row.template_id}}</template></el-table-column><el-table-column prop="data_contract" :label="t('printing.dataContract')" min-width="190"/><el-table-column :label="t('printing.state')" width="110"><template #default="{row}">{{t(row.enabled?'printing.enabled':'printing.disabled')}}</template></el-table-column><el-table-column v-if="can('publish')" :label="t('printing.operations')" width="100"><template #default="{row}"><el-button link type="primary" @click="editScene(row)">{{t('printing.edit')}}</el-button></template></el-table-column></el-table>
    </template>
    <template v-if="section==='queues'&&can('devices')"><header><h2>{{t('printing.flow.clientQueues')}}</h2></header><el-link href="/downloads/AppNexus-PrintClient-Windows-x64.zip" download type="primary">{{t('printing.flow.downloadClient')}}</el-link><el-alert :title="t('printing.flow.agentHint')" type="info" :closable="false"/><el-table :data="visible(queues)"><el-table-column prop="queue_name" :label="t('printing.queue')" min-width="200"/><el-table-column prop="site_code" :label="t('printing.site')"/><el-table-column prop="agent_id" :label="t('printing.flow.client')"/><el-table-column :label="t('printing.operations')" width="120"><template #default="{row}"><el-button link type="primary" :disabled="busy" @click="registerQueue(row)">{{t('printing.createDevice')}}</el-button></template></el-table-column></el-table></template>
    <template v-if="section==='documents'&&can('submit')"><header><h2>{{t('printing.flow.documents')}}</h2><el-button type="primary" :disabled="!scenes.some(value=>value.enabled)" @click="newDocument">{{t('printing.flow.createDocument')}}</el-button></header><el-table :data="visible(documents)" row-key="id"><el-table-column prop="number" :label="t('printing.flow.number')" min-width="180"/><el-table-column prop="scene_name" :label="t('printing.flow.scene')" min-width="180"/><el-table-column :label="t('printing.operations')" width="150"><template #default="{row}"><el-button link type="primary" @click="openOutput(row)">{{t('printing.flow.print')}}</el-button></template></el-table-column></el-table></template>
  </section>
  <ManagedDialog :model-value="contractOpen" :title="t('printing.flow.createContract')" :busy="busy" width="min(1000px, calc(100vw - 32px))" @update:model-value="contractOpen=$event">
    <el-alert :title="t('printing.flow.contractHint')" type="info" :closable="false"/><el-alert v-if="error" :title="error" type="error" :closable="false"/>
    <el-form label-position="top" @submit.prevent="saveContract"><el-form-item :label="t('printing.code')"><el-input v-model="contractForm.code" maxlength="64"/></el-form-item><el-form-item :label="t('printing.flow.chineseName')"><el-input v-model="contractForm.nameZh" maxlength="128"/></el-form-item><el-form-item :label="t('printing.flow.englishName')"><el-input v-model="contractForm.nameEn" maxlength="128"/></el-form-item><el-button :disabled="contractForm.fields.length>=50" @click="addContractField">{{t('printing.addField')}}</el-button>
    <el-table :data="contractForm.fields"><el-table-column type="expand"><template #default="{row}"><section v-if="row.columns" class="flow-workspace"><el-button :disabled="row.columns.length>=50" @click="addColumn(row)">{{t('printing.flow.addColumn')}}</el-button><el-table :data="row.columns"><el-table-column :label="t('printing.fieldName')"><template #default="{row:column}"><el-input v-model="column.key" maxlength="64"/></template></el-table-column><el-table-column :label="t('printing.flow.chineseName')"><template #default="{row:column}"><el-input v-model="column.labelZh" maxlength="128"/></template></el-table-column><el-table-column :label="t('printing.flow.englishName')"><template #default="{row:column}"><el-input v-model="column.labelEn" maxlength="128"/></template></el-table-column><el-table-column :label="t('printing.sampleValue')"><template #default="{row:column}"><el-input v-model="column.sample" maxlength="2000"/></template></el-table-column><el-table-column :label="t('printing.operations')"><template #default="{$index}"><el-button link type="danger" @click="row.columns.splice($index,1)">{{t('printing.flow.removeLine')}}</el-button></template></el-table-column></el-table></section></template></el-table-column><el-table-column :label="t('printing.flow.detailTable')" width="110"><template #default="{row}"><el-switch :model-value="!!row.columns" @update:model-value="value=>setFieldType(row,!!value)"/></template></el-table-column><el-table-column :label="t('printing.fieldName')" min-width="130"><template #default="{row}"><el-input v-model="row.key" maxlength="64"/></template></el-table-column><el-table-column :label="t('printing.flow.chineseName')" min-width="140"><template #default="{row}"><el-input v-model="row.labelZh" maxlength="128"/></template></el-table-column><el-table-column :label="t('printing.flow.englishName')" min-width="140"><template #default="{row}"><el-input v-model="row.labelEn" maxlength="128"/></template></el-table-column><el-table-column :label="t('printing.sampleValue')" min-width="150"><template #default="{row}"><el-input v-model="row.sample" maxlength="2000"/></template></el-table-column><el-table-column :label="t('printing.operations')" width="90"><template #default="{$index}"><el-button link type="danger" @click="contractForm.fields.splice($index,1)">{{t('printing.flow.removeLine')}}</el-button></template></el-table-column></el-table>
    <footer><el-button @click="contractOpen=false">{{t('organization.cancel')}}</el-button><el-button native-type="submit" type="primary" :loading="busy">{{t('organization.save')}}</el-button><el-button type="primary" :loading="busy" @click="designAfterSave=true;saveContract()">{{t('printing.flow.saveAndDesign')}}</el-button></footer></el-form>
  </ManagedDialog>
  <ManagedDialog :model-value="sceneOpen" :title="t('printing.flow.scenes')" :busy="busy" @update:model-value="sceneOpen=$event">
    <el-alert v-if="error" :title="error" type="error" :closable="false"/>
    <el-form ref="sceneFormRef" :model="sceneForm" :rules="sceneRules" label-position="top" @submit.prevent="saveScene"><el-form-item v-if="sceneForm.id" :label="t('printing.flow.sceneId')"><span class="scene-identifier">{{sceneForm.id}}</span><el-button link type="primary" :aria-label="t('printing.flow.copySceneId')" @click="copySceneIdentifier(sceneForm.id)">{{t('printing.flow.copy')}}</el-button></el-form-item><el-form-item :label="t('printing.flow.sceneCode')" prop="code"><el-input v-model="sceneForm.code" :readonly="!!sceneForm.id" maxlength="64"/><span class="field-hint">{{t('printing.flow.sceneCodeHint')}}</span></el-form-item><el-form-item :label="t('printing.name')" prop="name"><el-input v-model="sceneForm.name" maxlength="128"/></el-form-item><el-form-item :label="t('printing.template')" prop="templateId"><el-select v-model="sceneForm.templateId" @change="selectTemplate"><el-option v-for="value in matchingTemplates" :key="value.id" :value="value.id" :label="String(value.name)"/></el-select></el-form-item><el-form-item :label="t('printing.dataContract')"><el-input :model-value="String(sceneForm.contract||'')" readonly/><span class="field-hint">{{t('printing.flow.contractFromTemplate')}}</span></el-form-item><el-form-item :label="t('printing.copies')"><el-input-number v-model="sceneForm.copies" :min="1" :max="99"/></el-form-item><el-form-item :label="t('printing.enabled')"><el-switch v-model="sceneForm.enabled"/></el-form-item><footer><el-button @click="sceneOpen=false">{{t('organization.cancel')}}</el-button><el-button type="primary" native-type="submit" :loading="busy">{{t('organization.save')}}</el-button></footer></el-form>
  </ManagedDialog>
  <ManagedDialog :model-value="documentOpen" :title="t('printing.flow.createDocument')" :busy="busy" width="min(1100px, calc(100vw - 32px))" @update:model-value="documentOpen=$event">
    <el-alert v-if="error" :title="error" type="error" :closable="false"/>
    <el-form label-position="top" @submit.prevent="saveDocument"><el-form-item :label="t('printing.flow.scene')" required><el-select v-model="documentScene" @change="resetData"><el-option v-for="value in scenes.filter(value=>value.enabled)" :key="value.id" :value="value.id" :label="String(value.name)"/></el-select></el-form-item><el-form-item :label="t('printing.flow.number')" required><el-input v-model="number" maxlength="128"/></el-form-item><div class="flow-grid"><el-form-item v-for="field in scalarFields" :key="field.key" :label="english?field.labelEn:field.labelZh"><el-input-number v-if="field.type==='NUMBER'" v-model="data[field.key]" /><el-select v-else-if="field.type==='BOOLEAN'" v-model="data[field.key]"><el-option :value="true" :label="t('printing.booleanTrue')"/><el-option :value="false" :label="t('printing.booleanFalse')"/></el-select><el-input v-else v-model="data[field.key]" maxlength="2000" :disabled="field.key==='documentNumber'" :placeholder="field.key==='documentNumber'?number:''"/></el-form-item></div>
      <section v-for="field in tableFields" :key="field.key"><header><h3>{{english?field.labelEn:field.labelZh}}</h3><el-button :disabled="data[field.key]?.length>=500" @click="addLine(field.key)">{{t('printing.flow.addLine')}}</el-button></header><el-table :data="data[field.key]??[]"><el-table-column v-for="column in field.columns" :key="column.key" :label="english?column.labelEn:column.labelZh" min-width="140"><template #default="{row}"><el-input v-model="row[column.key]" maxlength="2000" :aria-label="english?column.labelEn:column.labelZh"/></template></el-table-column><el-table-column :label="t('printing.operations')" width="100"><template #default="{$index}"><el-button link type="danger" @click="data[field.key].splice($index,1)">{{t('printing.flow.removeLine')}}</el-button></template></el-table-column></el-table></section>
      <footer><el-button @click="documentOpen=false">{{t('organization.cancel')}}</el-button><el-button type="primary" native-type="submit" :loading="busy">{{t('organization.save')}}</el-button></footer>
    </el-form>
  </ManagedDialog>
  <ManagedDialog :model-value="outputOpen" :title="t('printing.flow.print')" :busy="busy" @update:model-value="outputOpen=$event">
    <el-alert v-if="error" :title="error" type="error" :closable="false"/><el-alert :title="t(output.outputType==='PDF'?'printing.flow.pdfHint':'printing.flow.outputHint')" type="info" :closable="false"/>
    <el-alert v-if="output.outputType==='PRINTER'&&!devices.some(value=>value.enabled)" :title="t('printing.flow.noDevices')" type="warning" :closable="false"/><el-form label-position="top" @submit.prevent="submit"><el-form-item v-if="output.outputType==='PRINTER'" :label="t('printing.device')" required><el-select v-model="output.deviceId"><el-option v-for="value in devices.filter(value=>value.enabled)" :key="value.id" :value="value.id" :label="String(value.name)+' / '+String(value.site_code)"/></el-select></el-form-item><el-form-item :label="t('printing.flow.output')"><el-radio-group v-model="output.outputType"><el-radio value="PDF">PDF</el-radio><el-radio value="PRINTER">{{t('printing.flow.physical')}}</el-radio></el-radio-group></el-form-item><el-form-item v-if="output.outputType==='PRINTER'" :label="t('printing.printMode')"><el-radio-group v-model="printMode"><el-radio value="PREVIEW">{{t('printing.previewThenPrint')}}</el-radio><el-radio value="SILENT">{{t('printing.silentPrint')}}</el-radio></el-radio-group></el-form-item><el-form-item v-if="output.outputType==='PRINTER'" :label="t('printing.copies')"><el-input-number v-model="output.copies" :min="1" :max="99"/></el-form-item><footer><el-button @click="outputOpen=false">{{t('organization.cancel')}}</el-button><el-button type="primary" native-type="submit" :disabled="output.outputType==='PRINTER'&&printMode==='SILENT'&&!output.deviceId" :loading="busy">{{t('printing.flow.print')}}</el-button></footer></el-form>
  </ManagedDialog>
</template>

